package com.bank.analytics;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AnalyticsDemo {
    private static final Logger log = Logger.getLogger(AnalyticsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int shardCount = 8;
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        PortfolioAnalyticsService svc = new PortfolioAnalyticsService(shardCount);

        // Math.sqrt for statistics (NOT money).
        List<Double> returns = List.of(0.012, -0.008, 0.015, -0.004, 0.009);
        double vol = svc.volatility(returns);
        log.info(() -> "Rajesh volatility = " + vol);

        // Math.floorMod for a NON-NEGATIVE shard index even with a negative hash.
        int shardR = svc.shardFor(rajesh.getAccountId());
        int shardP = svc.shardFor(priya.getAccountId());
        log.info(() -> "Shard SAV2001 = " + shardR + ", CUR3001 = " + shardP);

        // Demonstrate why % would be dangerous here.
        log.info(() -> "Plain % demo: -7 % 8 = " + (-7 % 8)
                + " (negative!), floorMod(-7,8) = " + Math.floorMod(-7, 8));

        // StrictMath for cross-platform reproducible compliance score.
        double score = svc.reproducibleScore(0.07, 3);
        log.info(() -> "Reproducible growth factor = " + score);

        // Classic Math.abs overflow note.
        log.warning(() -> "Math.abs(Integer.MIN_VALUE) = " + Math.abs(Integer.MIN_VALUE)
                + " (still negative — overflow trap)");

        // Balances stay BigDecimal; never routed through Math.
        log.info(() -> "Rajesh balance (BigDecimal) = " + rajesh.getBalance());
    }
}

