class PortfolioAnalyticsService {
    private static final Logger log = Logger.getLogger(PortfolioAnalyticsService.class.getName());
    private final int shardCount;

    PortfolioAnalyticsService(int shardCount) { this.shardCount = shardCount; }

    // Volatility = sqrt(variance). Legitimate Math.sqrt on a statistic.
    double volatility(java.util.List<Double> returns) {
        double mean = returns.stream().mapToDouble(Double::doubleValue).average().orElse(0.0);
        double variance = returns.stream()
                .mapToDouble(r -> Math.pow(r - mean, 2))   // Math.pow for squaring
                .average().orElse(0.0);
        return Math.sqrt(variance);                        // Math.sqrt for the root
    }

    // floorMod guarantees a non-negative index in [0, shardCount).
    int shardFor(String accountId) {
        int hash = accountId.hashCode();                   // can be negative
        return Math.floorMod(hash, shardCount);            // NEVER negative
    }

    // StrictMath gives bit-for-bit identical results across platforms.
    double reproducibleScore(double rate, int years) {
        return StrictMath.pow(1.0 + rate, years);
    }
}

